-- Fixup for 20260908050000: that migration's script died partway through
-- (Supabase's SQL editor runs a pasted multi-statement script as separate
-- auto-committed statements, not one atomic transaction), leaving Module 1's
-- and Module 3's "Embeddings & Semantic Search" inserts committed, but RAG,
-- Evaluating Agents, and Multi-Agent Systems never inserted. All 3 renumbering
-- passes from 050000 DID complete, so the order_index slots those 3 lessons
-- were meant to occupy are already reserved and empty -- no further
-- renumbering needed here, only the 3 missing INSERTs.
--
-- Anchored to lesson titles via subquery (not hardcoded order_index) so this
-- self-corrects even if the exact current numbers differ from what's assumed.

WITH new_lesson AS (
  INSERT INTO public.lessons (module_number, order_index, title, slug, summary, coin_cost, is_published)
  VALUES (
    3,
    (SELECT order_index FROM public.lessons WHERE module_number = 3 AND title = 'Embeddings & Semantic Search') + 1,
    'Retrieval-Augmented Generation (RAG)', 'retrieval-augmented-generation-rag',
    'How to make an LLM answer using YOUR real, current documents instead of just what it memorized during training.', 10, true
  )
  RETURNING id
), ins_content AS (
  INSERT INTO public.lesson_content (lesson_id, content)
  SELECT id, '{"hook":"Ask an LLM about your company''s return policy, and it will confidently make one up. RAG is how you fix that — permanently, without retraining anything.","explanation":"RAG stands for Retrieval-Augmented Generation, and it solves a real problem: an LLM only \"knows\" what was in its training data, frozen at some point in the past, with zero awareness of YOUR specific documents, live data, or anything created after training. Retraining a whole model just to teach it new facts is enormously expensive and slow. RAG sidesteps this entirely with a two-step pattern: (1) RETRIEVE — take the user''s question, turn it into an embedding, and search a database of your real documents for the most similar chunks (using exactly the semantic search from the last lesson); (2) GENERATE — hand those retrieved chunks to the LLM ALONGSIDE the original question, with an instruction like \"answer using ONLY the information below.\" The model now answers grounded in real, current, specific information instead of guessing from old training data — and because the retrieved source is visible, you can even show users exactly which document backed up the answer. This is the technique behind virtually every \"chat with your documents\" product.","analogy":"It''s an open-book exam versus a closed-book one. A plain LLM answers from memory alone (closed-book, and it might misremember). RAG hands the model the exact right page of the textbook FIRST, then asks the question (open-book) — a completely different, far more reliable, situation.","fun_fact":"RAG was introduced by Meta AI researchers in 2020, specifically to reduce hallucination — and it remains one of the single most effective, widely-used techniques for grounding LLM answers in real facts, years later.","try_it":"Think of a real question only YOUR school, company, or community could answer correctly (e.g. ''What time does the cafeteria close on Fridays?''). A generic LLM has never seen that. Sketch what document you''d need to retrieve to answer it correctly.","code":"import math\n\ndef cosine_similarity(a, b):\n    dot = sum(x * y for x, y in zip(a, b))\n    mag_a = math.sqrt(sum(x * x for x in a))\n    mag_b = math.sqrt(sum(y * y for y in b))\n    return dot / (mag_a * mag_b)\n\n# A tiny \"document store\" -- normally thousands of real chunks\ndocuments = [\n    {\"text\": \"The cafeteria closes at 3pm on Fridays.\", \"embedding\": [0.9, 0.1]},\n    {\"text\": \"The library is open until 8pm on weekdays.\", \"embedding\": [0.2, 0.9]},\n    {\"text\": \"Football practice is on Tuesdays and Thursdays.\", \"embedding\": [0.1, 0.3]},\n]\n\ndef retrieve(query_embedding, documents, top_k=1):\n    scored = [(cosine_similarity(query_embedding, d[\"embedding\"]), d) for d in documents]\n    scored.sort(key=lambda pair: pair[0], reverse=True)\n    return [doc for score, doc in scored[:top_k]]\n\n# 1) RETRIEVE: find the most relevant document for this question\nquestion = \"What time does the cafeteria close?\"\nquestion_embedding = [0.88, 0.12]  # pretend this came from an embedding model\nbest_matches = retrieve(question_embedding, documents)\n\n# 2) GENERATE: hand the retrieved text to the model, grounded in real info\ncontext = \"\\n\".join(doc[\"text\"] for doc in best_matches)\nprompt = f\"Answer using ONLY this information:\\n{context}\\n\\nQuestion: {question}\"\nprint(prompt)","visual":{"caption":"Two steps: find the right information, then answer using it","steps":[{"emoji":"❓","label":"User Question","caption":"A real question about something specific to you."},{"emoji":"🧠","label":"Embed the Question","caption":"Convert it into a vector, same as any embedding."},{"emoji":"🔍","label":"Retrieve Closest Docs","caption":"Semantic search finds the most relevant real documents."},{"emoji":"📎","label":"Combine Question + Text","caption":"Both go into the prompt together."},{"emoji":"✅","label":"Grounded Answer","caption":"The model answers using real, retrieved information."}]},"practice":{"prompt":"Why does RAG help an LLM answer accurately about YOUR specific, current documents?","options":["It retrieves the actual relevant text and gives it to the model as context, instead of relying on frozen training memory","It retrains the entire model on your documents every time you ask a question","It deletes the question and answers something unrelated instead","It has no real effect — the model already knows every document that exists"],"correct_index":0,"feedback":"RAG never retrains anything — it just hands the model the right real text at question time, the same way an open-book exam works."}}'::jsonb FROM new_lesson
  RETURNING lesson_id
)
INSERT INTO public.lesson_quiz_questions (lesson_id, order_index, question, options, correct_index, explanation)
SELECT ins_content.lesson_id, q.order_index, q.question, q.options::jsonb, q.correct_index, q.explanation
FROM ins_content, (VALUES
  (1, 'What does RAG stand for?', '["Retrieval-Augmented Generation","Rapid AI Generation","Random Answer Generator","Recursive Agent Grouping"]', 0, 'The name describes the two-step pattern exactly: retrieve relevant information, then generate an answer using it.'),
  (2, 'Why can''t you just ask an LLM directly about your company''s internal, private documents?', '["The LLM was never trained on those documents, so it has no real knowledge of them","LLMs refuse to answer any company-related question","It''s technically impossible to combine an LLM with any external data","LLMs automatically know every document that exists"]', 0, 'An LLM only knows what was in its training data — anything specific to you, created after training, was never seen at all.'),
  (3, 'In the RAG pattern, what happens in the RETRIEVE step?', '["The user''s question is used to search for the most relevant document chunks","The model is retrained from scratch on new data","The final answer is generated with no reference to any documents","A human manually looks up the answer"]', 0, 'Retrieval uses embeddings and similarity search — exactly the technique from the previous lesson — to find relevant chunks.'),
  (4, 'What happens in the GENERATE step of RAG?', '["The retrieved text is handed to the LLM along with the question, instructed to answer using only that information","The retrieved documents are deleted before the model sees them","The model ignores the retrieved text and answers from memory anyway","A new model is trained using only the retrieved documents"]', 0, 'The LLM is asked to answer grounded in the specific text it was just handed, rather than guessing from old training data.'),
  (5, 'Why was RAG specifically introduced as a technique?', '["To reduce hallucination by grounding answers in real, retrieved information","To make LLMs run faster on old hardware","To replace the need for any prompt at all","To make training data larger"]', 0, 'RAG was introduced by Meta AI researchers in 2020 specifically to address hallucination in ungrounded LLM answers.'),
  (6, 'In the code example, why did the cafeteria document get retrieved instead of the library or football documents?', '["Its embedding was numerically closest to the question''s embedding","It was listed first in the documents list, which always wins","The code was hardcoded to always pick that document","Cosine similarity cannot actually rank multiple documents"]', 0, 'Retrieval always picks the document(s) whose embedding is closest to the question''s embedding — here, that was clearly the cafeteria document.'),
  (7, 'What is the "open-book exam" analogy describing about RAG?', '["Giving the model the exact right source material before asking the question, instead of relying on memory alone","Letting students cheat during a real exam","Making exams easier by removing all questions","Testing a model with no information at all"]', 0, 'A plain LLM answers closed-book, from memory. RAG hands it the right page first — open-book — which is far more reliable.')
) AS q(order_index, question, options, correct_index, explanation);

WITH new_lesson AS (
  INSERT INTO public.lessons (module_number, order_index, title, slug, summary, coin_cost, is_published)
  VALUES (
    6,
    (SELECT order_index FROM public.lessons WHERE module_number = 6 AND title = 'Memory: Making Your Agent Remember') + 1,
    'Evaluating Agents: Did It Actually Work?', 'evaluating-agents',
    'A chatbot that sounds confident isn''t the same as one that''s actually right — here''s how real teams measure agent quality.', 10, true
  )
  RETURNING id
), ins_content AS (
  INSERT INTO public.lesson_content (lesson_id, content)
  SELECT id, '{"hook":"An agent can sound completely confident and still be completely wrong. \"Sounds good\" is not evaluation — here''s what actually is.","explanation":"Evaluating a normal ML model is straightforward: compare its prediction to a known correct answer (precision, recall, accuracy). Evaluating an AGENT is harder, because there often isn''t one single \"correct\" answer — a good response to \"help me plan a trip\" could take many valid forms. Real teams use a few concrete techniques: Task success rate — for tasks WITH a clear right answer (did the agent book the right flight? get the math right?), just check pass/fail across a test set of real scenarios, exactly like a model''s accuracy. LLM-as-judge — for open-ended tasks with no single right answer, use a SECOND LLM as an impartial grader, given a clear rubric (\"Is this response helpful? Accurate? On-topic?\"), scoring each response. Groundedness / faithfulness checking — specifically for RAG systems, checking whether the answer is actually SUPPORTED by the retrieved documents, or whether the model added claims that aren''t in them (a subtle form of hallucination). None of these are perfect, but skipping evaluation entirely means shipping an agent nobody has actually verified works — the same trap as an ML model whose creator never checked precision or recall.","analogy":"It is like grading an essay question instead of a multiple-choice test. There is no single correct string, so you build a rubric, and check the answer against IT — not against ''well it sounded confident.''","fun_fact":"LLM-as-judge is now common enough that entire benchmark suites (used by real research labs) are built around ONE strong model consistently grading many other models'' outputs against the same rubric — reproducible evaluation at a scale no human grading team could match.","try_it":"Pick one of the agent tasks from earlier lessons (planning a trip, answering support questions). Write ONE line of a rubric an LLM-judge could use to grade it — be specific enough that two different graders would agree.","code":"# TASK SUCCESS RATE: simple pass/fail against known-correct answers\ntest_cases = [\n    {\"question\": \"2 + 2\", \"expected\": \"4\", \"agent_answered\": \"4\"},\n    {\"question\": \"capital of Ghana\", \"expected\": \"Accra\", \"agent_answered\": \"Accra\"},\n    {\"question\": \"capital of Kenya\", \"expected\": \"Nairobi\", \"agent_answered\": \"Nakuru\"},\n]\npassed = sum(1 for t in test_cases if t[\"agent_answered\"] == t[\"expected\"])\nprint(f\"Task success rate: {passed}/{len(test_cases)}\")\n\n# GROUNDEDNESS CHECK: is every claim in the answer actually IN the source?\nretrieved_context = \"The cafeteria closes at 3pm on Fridays.\"\nagent_answer = \"The cafeteria closes at 3pm on Fridays, and it''s the best food on campus.\"\n\ndef is_grounded(answer, context):\n    # simplified: a real check uses another LLM call, not string matching\n    unsupported_claim = \"best food on campus\"\n    return unsupported_claim not in answer.lower()\n\nprint(f\"Fully grounded in retrieved context: {is_grounded(agent_answer, retrieved_context)}\")","visual":{"caption":"Three real ways to check an agent actually worked","steps":[{"emoji":"✅","label":"Task Success Rate","caption":"Pass/fail against known-correct answers, for well-defined tasks."},{"emoji":"⚖️","label":"LLM-as-Judge","caption":"A second model scores open-ended answers against a clear rubric."},{"emoji":"📎","label":"Groundedness Check","caption":"Is every claim actually supported by the retrieved source?"},{"emoji":"🔁","label":"Repeat & Track","caption":"Real, repeatable evaluation, run on every change — not a one-off vibe check."}]},"practice":{"prompt":"Why is \"it sounds confident\" not the same thing as evaluation?","options":["An agent can phrase a wrong answer just as confidently as a right one","Confidence and correctness are mathematically identical","Agents are incapable of sounding confident","This is only a concern for human speakers, never AI"],"correct_index":0,"feedback":"Tone has zero relationship to accuracy — that is exactly why real techniques like task success rate and groundedness checks exist."}}'::jsonb FROM new_lesson
  RETURNING lesson_id
)
INSERT INTO public.lesson_quiz_questions (lesson_id, order_index, question, options, correct_index, explanation)
SELECT ins_content.lesson_id, q.order_index, q.question, q.options::jsonb, q.correct_index, q.explanation
FROM ins_content, (VALUES
  (1, 'Why is evaluating an AGENT often harder than evaluating a plain ML model?', '["Many agent tasks have no single ''correct'' answer to compare against","Agents never make any mistakes, so evaluation is unnecessary","ML models are always harder to evaluate than agents","Evaluation is illegal for AI agents"]', 0, 'Unlike a model predicting spam/not-spam, an open-ended agent task like ''help me plan a trip'' can have many valid answers.'),
  (2, 'What is task success rate best suited for?', '["Tasks WITH a clear, checkable right answer, like booking the correct flight or getting math right","Every possible agent task, with no exceptions","Only tasks involving natural language, never numbers","Tasks where no correct answer could ever exist"]', 0, 'When there''s a clear right answer, you can just check pass/fail across a test set — the same idea as model accuracy.'),
  (3, 'What is "LLM-as-judge"?', '["Using a second LLM to score open-ended responses against a clear rubric","A model that judges legal court cases","A rule that says LLMs are always right","A technique that only works on multiple-choice questions"]', 0, 'For open-ended tasks with no single correct answer, a second LLM applies a defined rubric to grade the response.'),
  (4, 'What does a groundedness (or faithfulness) check specifically catch?', '["An answer that includes claims NOT actually supported by the retrieved source documents","Spelling mistakes in the final answer","Whether the answer was generated quickly enough","Whether the user liked the tone of the response"]', 0, 'It''s a subtle form of hallucination — the model adding something plausible-sounding that the source material never actually said.'),
  (5, 'In the code example, why did the groundedness check flag the cafeteria answer as NOT fully grounded?', '["The answer added ''best food on campus,'' a claim not present in the retrieved source","The cafeteria closing time itself was wrong","The code has a bug and always returns False","Groundedness checks can only ever return True"]', 0, 'The retrieved context never said anything about the food being the best — that opinion was invented by the model.'),
  (6, 'Why is "it sounds confident" NOT the same as "it''s actually correct"?', '["An agent can phrase a wrong answer just as confidently as a right one","Confidence and correctness are mathematically identical","Agents are incapable of sounding confident","This is only a concern for human speakers, never AI"]', 0, 'Tone has no relationship to accuracy — this is exactly why real evaluation techniques exist instead of just trusting how an answer reads.'),
  (7, 'What''s the risk of shipping an agent with NO evaluation at all?', '["Nobody has actually verified it works, the same as an ML model whose creator never checked precision or recall","There is no risk — untested agents always work correctly","Evaluation only matters for agents that use tools","Evaluation is only needed after something has already gone wrong publicly"]', 0, 'Skipping evaluation just means the failures haven''t been found YET — not that they don''t exist.')
) AS q(order_index, question, options, correct_index, explanation);

WITH new_lesson AS (
  INSERT INTO public.lessons (module_number, order_index, title, slug, summary, coin_cost, is_published)
  VALUES (
    6,
    (SELECT order_index FROM public.lessons WHERE module_number = 6 AND title = 'Memory: Making Your Agent Remember') + 2,
    'Multi-Agent Systems', 'multi-agent-systems',
    'Sometimes the best agent isn''t one smart generalist — it''s several specialists working together.', 10, true
  )
  RETURNING id
), ins_content AS (
  INSERT INTO public.lesson_content (lesson_id, content)
  SELECT id, '{"hook":"Instead of building one agent that tries to do everything, what if you built a team — each one an expert at exactly one thing?","explanation":"A multi-agent system splits a big job across SEVERAL specialized agents instead of one generalist trying to do everything. A common pattern: a Coordinator agent breaks the user''s request into subtasks and routes each one to the right specialist — a Research agent that searches for information, a Writer agent that drafts text, a Reviewer agent that checks the draft for accuracy before it''s shown to the user. Each specialist can have its OWN focused system prompt and tools, tuned for exactly its one job — the same way a small, focused team of human specialists often outperforms one generalist trying to juggle everything. The tradeoff: more agents means more coordination complexity, more cost (each agent may make its own LLM calls), and new failure modes (what happens if two agents disagree, or the coordinator misroutes a task?). It''s not free complexity — it''s worth it specifically when a task genuinely benefits from specialization, not by default. FORGE''s own Bot Battle Arena is a real example of multiple independent agents (each built by a different student) interacting in the same system.","analogy":"One person CAN write, research, and edit a whole book alone. But a publishing house instead uses a researcher, a writer, and an editor — each excellent at their own piece, handing work to each other in sequence. That''s a multi-agent system.","fun_fact":"Some of the most capable AI systems in production today aren''t a single giant model — they''re several smaller, specialized agents coordinating, because a focused specialist is often both cheaper AND more reliable at its one job than a generalist trying to do everything at once.","try_it":"Pick a complex task (like ''plan and run a fundraiser''). Split it into 3 specialist roles a multi-agent system could use, and name what each one is responsible for.","code":"def research_agent(topic):\n    return f\"[Research] Found 3 sources about {topic}.\"\n\ndef writer_agent(research_notes):\n    return f\"[Writer] Draft based on: {research_notes}\"\n\ndef reviewer_agent(draft):\n    issues = [] if \"sources\" in draft else [\"Draft has no cited sources\"]\n    return {\"approved\": len(issues) == 0, \"issues\": issues}\n\ndef coordinator(user_request):\n    print(f\"Coordinator received: {user_request}\")\n    research = research_agent(user_request)\n    print(research)\n    draft = writer_agent(research)\n    print(draft)\n    review = reviewer_agent(draft)\n    print(f\"Reviewer verdict: {review}\")\n    return draft if review[\"approved\"] else \"Sent back for revision\"\n\nresult = coordinator(\"the history of Ghana''s flag\")\nprint(f\"\\nFinal output: {result}\")","visual":{"caption":"A team of specialists instead of one generalist","steps":[{"emoji":"🧭","label":"Coordinator","caption":"Splits the user''s request into subtasks and routes each one."},{"emoji":"🔎","label":"Research Agent","caption":"Specialist focused only on finding information."},{"emoji":"✍️","label":"Writer Agent","caption":"Specialist focused only on drafting text."},{"emoji":"🔍","label":"Reviewer Agent","caption":"Specialist focused only on checking quality before it ships."},{"emoji":"📦","label":"Combined Result","caption":"Each specialist did one job well; together they did the whole task."}]},"practice":{"prompt":"What is the main tradeoff of using multiple specialized agents instead of one generalist agent?","options":["More coordination complexity and cost, in exchange for each agent being more focused and reliable at its job","There is no tradeoff — multi-agent systems are strictly better in every case","Multi-agent systems are always cheaper than a single agent","Multi-agent systems eliminate the need for any evaluation"],"correct_index":0,"feedback":"Extra agents mean extra LLM calls and real coordination overhead — worth it specifically when a task genuinely benefits from specialization."}}'::jsonb FROM new_lesson
  RETURNING lesson_id
)
INSERT INTO public.lesson_quiz_questions (lesson_id, order_index, question, options, correct_index, explanation)
SELECT ins_content.lesson_id, q.order_index, q.question, q.options::jsonb, q.correct_index, q.explanation
FROM ins_content, (VALUES
  (1, 'What is a multi-agent system?', '["Several specialized agents working together on different parts of a task, instead of one generalist doing everything","A single agent that runs on multiple computers at once","A chatbot with more than one system prompt loaded simultaneously","An agent that can only handle one task per day"]', 0, 'Each specialist agent focuses on one job — research, writing, review — rather than one agent trying to juggle all of them.'),
  (2, 'In the coordinator pattern from this lesson, what is the Coordinator agent''s job?', '["Break the user''s request into subtasks and route each to the right specialist agent","Do all the actual work itself, ignoring every other agent","Only handle billing and payments","Replace the need for any specialist agents entirely"]', 0, 'The coordinator''s whole role is decomposition and routing — the specialists do the actual work.'),
  (3, 'In the code example, what did the Reviewer agent check before approving the draft?', '["Whether the draft actually referenced sources from the research step","Whether the draft was under 100 words","Whether the user had paid for the service","Nothing — the reviewer always approves everything"]', 0, 'The reviewer specifically checked for the word ''sources'' in the draft as a simplified stand-in for a real citation check.'),
  (4, 'What is the main tradeoff of using multiple specialized agents instead of one generalist agent?', '["More coordination complexity and cost, in exchange for each agent being more focused and reliable at its job","There is no tradeoff — multi-agent systems are strictly better in every case","Multi-agent systems are always cheaper than a single agent","Multi-agent systems eliminate the need for any evaluation"]', 0, 'Extra agents mean extra LLM calls, more places for something to go wrong, and real coordination overhead — worth it only when specialization genuinely helps.'),
  (5, 'What real FORGE feature is a concrete example of multiple independent agents interacting in the same system?', '["Bot Battle Arena","The lesson quiz system","The Python linter","The device-token login system"]', 0, 'Bot Battle Arena pits independently-built student bots against each other — a real, live example of multiple agents interacting.'),
  (6, 'Why might a team choose several small, focused agents over one giant generalist agent?', '["A focused specialist is often more reliable AND cheaper at its one job than a generalist trying to do everything at once","Generalist agents are always technically impossible to build","Small agents always run instantly with zero cost","There is no meaningful difference between the two approaches"]', 0, 'This mirrors how human specialist teams often outperform one person trying to do every role alone.'),
  (7, 'What new failure mode does a multi-agent system introduce that a single agent doesn''t have?', '["Two agents disagreeing, or the coordinator misrouting a task to the wrong specialist","The complete inability to ever make a mistake","Running out of electricity","Needing a human to type every single prompt manually"]', 0, 'Coordination itself becomes a new source of error — a risk that simply doesn''t exist when there''s only one agent.')
) AS q(order_index, question, options, correct_index, explanation);
